"""Offline HTML reports from both frozen captures and cited RobStride data."""
from pathlib import Path
import json
import numpy as np
import pandas as pd
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from analyze_joint_telemetry import table, sha256
from build_run_report import STYLE, figure_html

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'docs/reports'
E=ROOT/'docs/motor_selection_evidence'
V=Path('/home/susan/.codex/visualizations/2026/09/09/01a08454-a5fd-7c81-81f6-9f09ce47d397')
SPEC='https://github.com/RobStride/Product_Information/blob/main/灵足时代RS系列产品规格介绍(260713）.pdf'
GATES='https://gates.com/content/dam/gates/home/knowledge-center/mectrol/whitepapers/timing-belt-theory-white-paper.pdf'

def page(title, subtitle, body, filename):
    js='''<dialog id="zoom"><button onclick="this.parentElement.close()">Close enlarged chart</button><img alt="Enlarged chart"></dialog><script>document.querySelectorAll('figure img').forEach(x=>{x.tabIndex=0;function show(){const d=document.querySelector('#zoom');d.querySelector('img').src=x.src;d.querySelector('img').alt=x.alt;d.showModal()}x.onclick=show;x.onkeydown=e=>{if(e.key==='Enter')show()}});</script>'''
    s=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><style>{STYLE}svg{{max-width:100%;height:auto}}.eq{{font-family:monospace;background:white;padding:15px;overflow:auto}}header a{{color:#9de0d3}}</style><header><div><div class="eyebrow">Rexmi hardware · 10 September 2026</div><h1>{title}</h1><p>{subtitle}</p><button onclick="window.print()">Print / save PDF</button></div></header><nav><div><a href="rexmi-hardware-report.html">Combined test runs · Rev D</a><a href="robstride-motor-selection.html">RobStride motor selection · Rev 1</a></div></nav><main>{body}</main><footer>Offline, self-contained figures. Click a chart to enlarge. Engineering design baseline; not hardware qualification.</footer>{js}</html>'''
    (OUT/filename).write_text(s)
    (V/filename).write_text(s)
    return s

def tab(df, cols, labels): return table(df,cols,labels)

def main():
    OUT.mkdir(exist_ok=True,parents=True)
    manifest=json.loads((E/'manifest.json').read_text())
    joint=pd.read_csv(E/'joint_envelope.csv')
    per=pd.read_csv(E/'per_run_joint_metrics.csv')
    frames=[]; full=[]; contact_rows=[]; collision_rows=[]
    for source in manifest['sources']:
        run=ROOT/'logs/telemetry'/source['run_id']
        assert sha256(run/'samples.csv')==source['hashes']['samples.csv']
        raw=pd.read_csv(run/'samples.csv'); full.append(raw)
        f=raw.loc[raw.sim_time_s>=2].copy(); f['run_id']=source['run_id']; frames.append(f)
        forces=np.stack([f[[f'contact.{leg}_foot.{a}_N' for a in ['fx_w','fy_w','fz_w']]].to_numpy() for leg in ['FL','FR','RL','RR']],axis=1)
        count=(np.linalg.norm(forces,axis=2)>5).sum(axis=1)
        contact_rows.append([100*np.mean(count==i) for i in range(5)])
        for c in f:
            if c.startswith('contact.') and c.endswith('.fx_w_N'):
                name=c.split('.')[1]
                if name.endswith('_foot'):continue
                norm=np.linalg.norm(f[[f'contact.{name}.{a}_N' for a in ['fx_w','fy_w','fz_w']]],axis=1)
                if norm.max()>5:
                    k=norm.argmax()
                    collision_rows.append(dict(run=source['run_id'],body=name,pct=100*np.mean(norm>5),peak=float(norm[k]),time=float(f.sim_time_s.iloc[k])))
    f=pd.concat(frames,ignore_index=True)
    assert len(f)==78988
    names=joint.joint.tolist()
    plt.rcParams.update({'font.size':10,'axes.spines.top':False,'axes.spines.right':False})
    fig,ax=plt.subplots(figsize=(12,4.5),layout='constrained')
    x=np.arange(16)
    for i,(source,color) in enumerate(zip(manifest['sources'],['#007b76','#b45c29'])):
        vals=per[per.run_id==source['run_id']].set_index('joint').loc[names].rms_est_Nm
        ax.bar(x+(i-.5)*.35,vals,.35,label=f'Run {i+1}',color=color)
    ax.set_xticks(x,[n.replace('_joint','').replace('calf','knee').replace('foot','wheel') for n in names],rotation=55,ha='right')
    ax.set_ylabel('Run RMS estimated torque (Nm)');ax.legend();ax.grid(axis='y',alpha=.2)
    rmsfig=figure_html(fig,'Both runs: RMS by joint','Run 1 remains the worst knee RMS case. Run 2 was harsher by operator intent but 13.2% lighter; do not replace run 1 with run 2.')
    fig,axes=plt.subplots(2,2,figsize=(12,8),layout='constrained')
    for ax,kind,label in zip(axes.flat,['hip','thigh','calf','foot'],['Hip ab/ad','Thigh pitch','Knee','Wheel']):
        for i,ff in enumerate(frames):
            for j in [n for n in names if f'_{kind}_' in n]:
                ax.scatter(ff[j+'.velocity_rad_s'],ff[j+'.torque_applied_est_Nm'],s=.6,alpha=.12,color=['#007b76','#b45c29'][i],rasterized=True)
            ax.plot([],[],'.',color=['#007b76','#b45c29'][i],label=f'Run {i+1}')
        ax.set(title=label,xlabel='Angular velocity (rad/s)',ylabel='Applied estimate (Nm)');ax.legend();ax.grid(alpha=.2)
    scatter=figure_html(fig,'Combined torque-speed trajectories','All retained samples. Torque and velocity have a ~5 ms sampling offset. These are actuator-model estimates, not measured shaft torque. Both motoring and braking quadrants are retained.')
    fig,ax=plt.subplots(figsize=(10,3.8),layout='constrained')
    for i,row in enumerate(contact_rows):ax.bar(np.arange(5)+(i-.5)*.35,row,.35,label=f'Run {i+1}',color=['#007b76','#b45c29'][i])
    ax.set(xticks=range(5),xlabel='Number of active foot contacts (>5 N)',ylabel='Retained time (%)');ax.legend();ax.grid(axis='y',alpha=.2)
    contactsfig=figure_html(fig,'Contact counts in both runs','Contact activity is reconstructed from normal-force-vector magnitudes. It is not a stability test, full reaction measurement or equal-load-sharing assumption.')
    fig,axes=plt.subplots(2,1,figsize=(12,6),layout='constrained')
    for i,ff in enumerate(frames):
        axes[i].plot(ff.sim_time_s,ff['RR_calf_joint.torque_applied_est_Nm'],lw=.5,color='#007b76',label='RR knee applied estimate')
        axes[i].plot(ff.sim_time_s,ff['RR_calf_joint.torque_demand_est_Nm'],lw=.4,alpha=.65,color='#b45c29',label='Uncapped PD request')
        axes[i].set(title=f'Run {i+1}',xlabel='Time within capture (s)',ylabel='Torque (Nm)');axes[i].legend(ncol=2);axes[i].grid(alpha=.2)
    history=figure_html(fig,'Rear-right knee across both captures','Separate capture time axes; no artificial connection between runs. The 23.5 Nm applied cap is accepted for the demonstrated motions.')
    cols=['joint','rms_est_Nm','worst_run_rms_Nm','max_10s_rms_est_Nm','peak_abs_est_Nm','max_abs_speed_rad_s','clipped_time_pct','longest_clip_s']
    labels=['Joint','Pooled RMS Nm','Worst run RMS Nm','Worst 10 s RMS Nm','Peak Nm','Max rad/s','Clipped %','Longest clip s']
    runrows=[]
    for i,s in enumerate(manifest['sources']):runrows.append({'run':i+1,'mass':s['mass_kg'],'full':s['full_rows']*.005,'kept':s['retained_rows']*.005,'rows':s['retained_rows']})
    full_rows=[]
    for j in names:
        arrays=[r[j+'.torque_applied_est_Nm'].to_numpy() for r in full]
        full_rows.append({'joint':j,'rms':max(float(np.sqrt(np.mean(a*a))) for a in arrays),'peak':max(float(abs(a).max()) for a in arrays)})
    body=f'''<section><h2>What the two tests establish</h2><div class="grid"><div class="card"><div class="label">Combined retained motion</div><div class="value">394.94 <small>s</small></div><p>78,988 samples · 16 joints · 200 Hz</p></div><div class="card"><div class="label">Accepted leg command cap</div><div class="value">23.5 <small>Nm</small></div><p>Not the 65.86 Nm uncapped PD spike</p></div><div class="card"><div class="label">Worst knee 10-second RMS</div><div class="value">22.08 <small>Nm</small></div><p>Rear-right knee, run 1</p></div></div><ul><li>Rear-right knee still governs sustained-load screening: <b>15.80 Nm worst-run RMS</b>; pooled RMS is 14.18 Nm.</li><li>Thigh requires loaded speed: <b>19.83 Nm at 30.05 rad/s</b>, not merely an unloaded velocity peak.</li><li>Wheels require separate selection: FR reaches <b>21.02 Nm at 61.50 rad/s while motoring</b>; RR reaches <b>18.62 Nm at 79.00 rad/s while braking</b>.</li><li>Exactly three active foot contacts: <b>52.54%</b>; fewer than three: <b>30.51%</b>.</li></ul><div class="note warn">Simulation evidence, not hardware validation. The applied effort is an implicit-PD clipped estimate. Torque is evaluated at substep start and velocity at substep end (~5 ms later). No winding temperature, calibrated shaft torque, electrical current or true terrain slope was measured.</div></section>
<section><h2>Capture coverage and mass</h2>{tab(pd.DataFrame(runrows),['run','mass','full','kept','rows'],['Run','Mass kg','Full duration s','Analyzed s','Analyzed rows'])}<p>Run 1: 9 September. Run 2: 10 September, operator requested harsher driving. Both complete captures have uniform 5 ms spacing; no automatic resets. First 2 s of each excluded from primary statistics as placement/landing sensitivity cut; full data are preserved below. Windows and continuous durations never cross run boundaries.</p><p>21.77 kg versus 18.89 kg are randomized runtime masses, not the same explicit 2 kg payload mounting. Operator labels do not prove terrain slope. Body tilt is not slope: maxima were 51.31° and 59.64°. Runtime USD was the rexmi_dog reskin.</p></section>
<section><h2>All 16 joints</h2>{rmsfig}{tab(joint,cols,labels)}<p class="small">Calf = knee; foot = wheel. All peak/speed/10-second values preserve the worst across both runs. Pooled RMS and clipping percentages are duration weighted, not mission weighted. Maxima in different columns need not coincide.</p><details><summary>Full-capture sensitivity, including first 2 seconds</summary>{tab(pd.DataFrame(full_rows),['joint','rms','peak'],['Joint','Worst full-run RMS Nm','Full-capture peak Nm'])}</details></section>
<section><h2>Torque, speed and clipping</h2>{scatter}{history}<ul><li>RR knee clipping: <b>7.75% pooled</b>, 12.70% run 1 and 4.48% run 2. Longest contiguous episode is 1.36 s, at low speed.</li><li>Largest knee PD request: <b>65.86 Nm</b>, FL knee at 226.265 s in run 2. Applied estimate remained 23.5 Nm. A base contact occurred about 40 ms earlier. A near-vertical obstacle is the operator's hypothesis, not measured ground geometry.</li><li>Wheel braking point is about −1.47 kW estimated mechanical power, not recovered battery power. FR high-speed motoring point is about +1.29 kW. Preserve these events rather than dismiss them as unloaded spin.</li><li>Logged limits and achieved speeds disagree for wheels. The installed implicit actuator ignores the deprecated velocity_limit setting; a realistic torque–speed replay is still needed.</li></ul></section>
<section><h2>Contacts and impacts</h2>{contactsfig}<p>Combined time: 0 contacts 0.57%; 1 contact 4.44%; 2 contacts 25.50%; 3 contacts 52.54%; 4 contacts 16.94%.</p><h3>Non-wheel normal-contact activity</h3>{tab(pd.DataFrame(collision_rows),['run','body','pct','peak','time'],['Capture','Body','Time >5 N %','Peak normal-vector N','Peak time s'])}<p>Sensor net_forces_w contains summed <b>normal</b> forces in world coordinates; tangential friction forces are not included. Vector magnitudes are not bearing reactions or complete impact loads. Contacts can occur against obstacle sides; multiple normals can cancel. The original contact-count field was blank, so counts are reconstructed from saved *_foot vectors without changing raw logs.</p><div class="note warn">Run 2 includes head, calf and base impacts. The acceptable 23.5 Nm command cap does not cap external shock torque or protect gears/bearings by itself.</div></section>
<section><h2>Design handoff</h2><p>Use the <a href="robstride-motor-selection.html">RobStride selection report</a> for motors, the 2:1 knee belt stage and qualification conditions. No assumed 150 mm support arm or mission-to-force conversion is used here.</p><details><summary>Traceability and reproducibility</summary><p>Raw captures remain local and unchanged. SHA-256 identities below. Rebuild the union with scripts/merge_joint_runs.py and these reports with scripts/build_combined_reports.py. Summary exports preserve per-run metrics as well as pooled results.</p><pre style="white-space:pre-wrap;overflow-wrap:anywhere">{json.dumps(manifest,indent=2)}</pre></details></section>'''
    report=page('Combined teleop test report · Rev D','Both test runs, real joint trajectories, contacts and the accepted torque cap.',body,'rexmi-hardware-report.html')
    (V/'rexmi-hardware-report-revD.html').write_text(report)
    motor_report(f,joint)

def motor_report(f,joint):
    # Manufacturer tabulated 48 V loaded curve, July 13 2026 PDF p32.
    speeds=np.array([280,320,390,426,430.]); torques=np.array([36,30,20,11,5.])
    def limit(rpm):
        # Constant peak below first tabulated speed is a screening assumption.
        # No extrapolation beyond highest loaded data point.
        return np.interp(rpm,speeds,torques,left=36,right=np.nan)
    screening=[]
    fig,axes=plt.subplots(1,3,figsize=(13,4.5),layout='constrained')
    for ax,kind,N,eta,title in zip(axes,['hip','thigh','calf'],[1,1,2],[1,1,.95],['Hip · direct RS06','Thigh · direct RS06','Knee · RS06 + 2:1 belt']):
        all_t=[];all_v=[]
        for j in joint.joint[joint.joint.str.contains('_'+kind+'_')]:
            t=f[j+'.torque_applied_est_Nm'].to_numpy();v=f[j+'.velocity_rad_s'].to_numpy()
            mask=t*v>0
            all_t.extend(abs(t[mask])/(eta*N));all_v.extend(abs(v[mask])*N*60/(2*np.pi))
        mt=np.array(all_t);mv=np.array(all_v);bound=limit(mv)
        outside=(mt>bound)|~np.isfinite(bound)
        screening.append(dict(family=title,ratio=N,efficiency=eta,motoring_samples=len(mt),outside=int(outside.sum()),max_module_rpm=float(mv.max()),max_module_Nm=float(mt.max())))
        ax.scatter(mv,mt,s=.5,alpha=.15,color='#007b76',rasterized=True)
        ax.plot(np.r_[0,speeds],np.r_[36,torques],color='#b45c29',lw=2,label='Loaded 48 V screen')
        ax.plot([100,160,220,280,340,400],[11.2,11,10.5,9.87,9.4,9.3],color='#344f99',ls='--',label='Thermal equilibrium')
        ax.set(title=title,xlabel='Module output rpm',ylabel='Module output torque (Nm)',ylim=(0,40),xlim=(0,450));ax.grid(alpha=.2);ax.legend(fontsize=8)
    curveplot=figure_html(fig,'RS06 loaded-curve comparison','Motoring samples only, mapped to module output; knee stage assumes 95% efficiency. Piecewise-linear interpolation of vendor loaded points; constant 36 Nm below 280 rpm is an explicit screening assumption. Thermal curve requires a 200 × 200 mm aluminum heatsink. No regenerative envelope is established.')
    (E/'robstride_screen.json').write_text(json.dumps(screening,indent=2)+'\n')
    print(json.dumps(screening,indent=2))
    ratio=[]
    for N in [1,1.5,1.75,2,2.25,2.5]:
        eta=1 if N==1 else .95
        rpm=20.091768*N*60/(2*np.pi)
        need=23.5/(eta*N);avail=float(limit(rpm))
        ratio.append(dict(N=N,rms=15.797776/(eta*N),ten=22.084766/(eta*N),peak=need,rpm=rpm,available=avail,status='outside tabulated loaded curve' if not np.isfinite(avail) else ('peak rectangle clears' if need<=avail else 'peak rectangle fails')))
    diagram='''<figure><svg viewBox="0 0 900 245" role="img" aria-label="RS06 internal 9 to 1 planetary drives a 24 tooth pulley and belt to a 48 tooth knee pulley, yielding total 18 to 1"><rect width="900" height="245" fill="#fff"/><g font-family="system-ui" fill="#172d39"><rect x="25" y="65" width="240" height="90" rx="10" fill="#e2eeeb" stroke="#007b76"/><text x="45" y="95" font-size="20">RS06 · internal 9:1</text><text x="45" y="125" font-size="16">Mounted on upper leg</text><path d="M265 110H335" stroke="#172d39" stroke-width="5"/><circle cx="380" cy="110" r="28" fill="#cce4e0" stroke="#007b76" stroke-width="3"/><circle cx="700" cy="110" r="56" fill="#cce4e0" stroke="#007b76" stroke-width="3"/><path d="M377 82L695 54M377 138L695 166" stroke="#ae491f" stroke-width="6"/><text x="355" y="195" font-size="18">24 teeth</text><text x="668" y="195" font-size="18">48 teeth</text><text x="470" y="110" font-size="18">2:1 belt stage</text><text x="630" y="28" font-size="18">Knee output</text><text x="35" y="225" font-size="15">Concept only · independent pulley bearings · tension adjustment · output encoder</text></g></svg><figcaption>Parallel-axis synchronous belt stage. The motor output turns twice per knee revolution; the internal 9:1 is not applied twice. Illustrative layout, not a released drawing.</figcaption></figure>'''
    body=f'''<section><h2>Selection: one leg motor SKU, two transmissions</h2><div class="note"><b>Use RobStride RS06 for all 12 leg joints.</b> Direct output for hip and thigh; <b>2:1 synchronous toothed-belt reduction for each knee</b>. Total rotor-to-knee ratio is <b>18:1</b>. This supersedes the earlier CubeMars design baseline.</div><div class="table-wrap"><table><tr><th>Joint / quantity</th><th>Motor</th><th>External ratio</th><th>Total ratio</th><th>Command cap at joint</th><th>Status</th></tr><tr><td>Hip ab/ad ×4</td><td>RS06</td><td>1:1 direct</td><td>9:1</td><td>23.5 Nm</td><td>Selected for prototype qualification</td></tr><tr><td>Thigh pitch ×4</td><td>RS06</td><td>1:1 direct</td><td>9:1</td><td>23.5 Nm</td><td>Selected for prototype qualification</td></tr><tr><td>Knee ×4</td><td>RS06</td><td>2:1 belt</td><td>18:1</td><td>23.5 Nm</td><td>Selected architecture; belt width/hardware provisional</td></tr><tr><td>Wheel ×4</td><td>No qualified RS SKU</td><td>Unreleased</td><td>Unreleased</td><td>23.7 Nm</td><td>Current wheel envelope cannot be silently reduced</td></tr></table></div><p>At the <a href="https://www.robstride.com/">manufacturer's advertised US retail price</a> of $210 per RS06, twelve leg modules total <b>$2,520</b>, excluding shipping, taxes, belts, bearings and wheels. The July specification separately lists ¥849 per module; this is a different market price, not a converted quote. Motor mass is <b>7.452 kg</b> before transmissions and cooling. CAD must reconcile replacement link masses/inertias; do not add this number directly to the USD total.</p><p>Selection is for the demonstrated capped motions, not jumps or handstands. Full-set procurement remains conditional on mounting/cooling and physical waveform tests.</p></section>
<section><h2>Why RS06, not a larger but slower QDD?</h2><p><a href="{SPEC}">RobStride's 13 July 2026 specification</a>, pages 31–33, provides a usable loaded curve and overload tables. RS06 is 621 g, internal 9:1, nominal 48 V, specified operating range 15–60 V, 36 Nm peak. The 11 Nm rating is measured at 100 rpm with a <b>200 × 200 mm aluminum heatsink</b>; it is not an enclosed-leg guarantee.</p><ul><li><b>RS02 direct:</b> 17 Nm peak is below the accepted leg cap. Additional gearing trades away the thigh speed and does not give the knee the same thermal margin.</li><li><b>RS03 / RS04 direct knee:</b> nominal no-load speeds are only 195 / 200 rpm, close to the measured knee's 191.86 rpm. Loaded speed is lower; high peak torque alone does not solve this.</li><li><b>RS06:</b> its loaded data include 20 Nm at 390 rpm and 36 Nm at 280 rpm. A 2:1 knee stage uses that speed capacity to lower motor torque.</li></ul>{curveplot}{tab(pd.DataFrame(screening),['family','motoring_samples','outside','max_module_rpm','max_module_Nm'],['Assembly','Motoring samples','Outside screening curve','Max module rpm','Max module torque Nm'])}<p class="small">Each sample is a joint-time observation, not an independent trial. Zero outside means only the stated nominal-voltage screen passed. This is not a thermal, tolerance, low-battery, braking or controller-bandwidth qualification. Do not extrapolate the curve beyond 430 rpm. Published speed tolerances and torque/velocity sampling offset remain material.</p></section>
<section><h2>Knee: select 2:1, not 3:1</h2>{diagram}<div class="eq">N = ωmodule / ωknee = 48 / 24 = 2<br>τmodule ≈ τknee / (ηN), η = 0.95 assumed for forward motoring<br>Worst-run RMS: 15.80 / 1.90 = 8.31 Nm<br>Worst 10-second RMS: 22.08 / 1.90 = 11.62 Nm<br>At joint cap: 23.5 / 1.90 = 12.37 Nm<br>Maximum module speed: 20.09 × 2 × 60 / (2π) = 383.72 rpm</div><p>The conservative rectangle of <b>12.37 Nm at 383.72 rpm</b> falls below the nominal loaded curve, which interpolates to about <b>20.90 Nm</b> there. This pairs separate maxima deliberately as a conservative screen, unlike claiming they occurred together. At 90% stage efficiency the capped module demand is 13.06 Nm; speed is unchanged.</p>{tab(pd.DataFrame(ratio),['N','rms','ten','peak','rpm','available','status'],['Extra ratio','Module run RMS Nm','Module 10 s RMS Nm','Module cap Nm','Module max rpm','Curve torque Nm','Endpoint screen'])}<ul><li>2:1 lowers knee RMS enough to be useful while retaining nominal loaded-speed headroom. 2.25:1 already exceeds the last tabulated loaded-speed point at the maximum measured knee speed.</li><li>Thermal reality: continuous stall rating is only <b>8 Nm</b> at module output; 11 Nm stall is listed for 200 s and 17 Nm for 15 s. Do not claim indefinite capped knee holding: 12.37 Nm exceeds continuous stall rating.</li><li>Vendor rotating overload table gives 17 Nm for 200 s, but it is not a repeated-cycle thermal model. The 11.62 Nm worst 10-second RMS and 1.36 s capped interval are plausible bench targets, not proof of 60-minute endurance.</li><li>Vendor low-speed equivalent inertia is 0.012 kg·m² at module output. Ideal extra 2:1 reflection gives <b>0.048 kg·m² at the knee</b> before external pulleys. Verify the vendor definition and put this in the dynamics model; extra reduction is not free.</li></ul></section>
<section><h2>Belt transmission: the prototype choice</h2><p><b>Use an enclosed synchronous toothed belt with an adjustable, locked tension setting.</b> Start CAD with a 24-tooth driver and 48-tooth knee pulley, 5 mm pitch, <b>20 mm belt width as a packaging allowance—not a released belt specification</b>. Select the final compatible tooth profile, cord construction, width and length using the manufacturer's load/life calculation.</p><div class="grid wide"><div class="card"><h3>Calculated geometry and forces</h3><ul><li>Pitch diameters: 38.20 mm driver; 76.39 mm driven.</li><li>At 23.5 Nm knee output, belt-span tension difference ΔF = τ/r = <b>615 N</b>.</li><li>At 213 mm pulley center distance, approximate small-pulley wrap is <b>169.7°</b>, about 11.3 teeth engaged; open-belt pitch length ≈607.7 mm.</li><li>These are design-geometry calculations, not a return to a hypothetical support lever arm. Actual pulley centers and belt path must come from SolidWorks. Do not alter the 213 mm leg geometry merely to fit a stock belt.</li></ul></div><div class="card"><h3>What tensioning does—and does not do</h3><ul><li>Preload prevents slack and tooth ratcheting; it does not eliminate tensile-cord stretch, tooth compliance or mount deflection.</li><li>Ideal equal-span no-slack lower bound: T₀ &gt; ΔF/2 ≈308 N per span. <b>Not an installation tension specification.</b> Dynamic load, tooth profile, width and vendor guidance determine the real value.</li><li>Near-parallel-span shaft radial load is approximately Ttight + Tslack, not ΔF alone. Include pretension in bearing and housing loads.</li><li>Use independent supported pulley shafts if the actuator output cannot carry the belt overhung load. Set tension with a gauge, lock the adjuster and provide inspection access.</li></ul></div></div><p>Use <a href="{GATES}">Gates' timing-belt theory</a> and its <a href="https://www.gates.com/us/en/knowledge-center/calculators/powergrip-tension-calculator.html">tension calculator</a> for the chosen belt family. A generic belt width or 'tight enough' setting is not a tooth-jump or fatigue calculation.</p><h3>Proposed stiffness acceptance test</h3><p>Initial engineering target: ≤0.5° elastic knee deflection at 23.5 Nm, measured across the external transmission, equivalent to <b>kθ ≥2,693 Nm/rad</b>. This is a proposed target, not a measured Unitree value. Measure reversal hysteresis separately; tighten the target if policy replay shows sensitivity.</p><div class="eq">Ideal two-span belt model: kθ ≈ 2(EA/Lspan) routput²<br>θtotal = θbelt + θteeth + θshaft + θbearings/housing<br>Required measured EA and tooth stiffness come from the selected belt, not assumed material modulus.</div><p>Add an encoder at the actual knee output: the RS06's output encoder is upstream of the external belt and cannot directly detect belt deflection or a skipped tooth. If the motor housing is mounted to the moving upper leg, qmodule = 2qknee + offset (with calibrated sign). A body-fixed housing needs a coupled coordinate mapping instead; do not blindly apply this equation.</p></section>
<section><h2>What Unitree does, and when bevel gears make sense</h2><p><a href="https://www.simplexitypd.com/blog/unitree-go2-quadruped-robot-dog-teardown/">Simplexity's first-hand Go2 teardown</a> establishes integrated planetary joint actuators and shows the opened leg. The actuator's planetary reduction and any remote knee transmission are <b>different stages</b>. The <a href="https://www.ifixit.com/News/109048/unitree-go2-is-an-impressively-affordable-robot-dog-but-is-it-repairable">iFixit teardown/CT</a> is another primary reference. The exact Go2-W knee stage and tooth ratio are not verified here; do not label a Go2 patent or a motor-only teardown as a production Go2-W BOM.</p><div class="table-wrap"><table><tr><th>Choice</th><th>Benefit</th><th>Cost / failure modes</th><th>Decision</th></tr><tr><td>2:1 synchronous belt</td><td>Remote proximal motor; adjustable ratio; accessible fabrication and replacement</td><td>Preload, tooth jump, elastic stretch, debris, bearing loads; output encoder needed</td><td>Prototype baseline</td></tr><tr><td>Longitudinal shaft + bevel pairs</td><td>Compact enclosed torque path; can provide high stiffness if correctly sized</td><td>Usually two right-angle meshes for parallel motor/knee axes; backlash, axial thrust, gear contact, bearing preload and housing alignment</td><td>Fallback if belt stiffness/packaging test fails</td></tr><tr><td>Motor directly at knee</td><td>Few external parts and no belt adjustment</td><td>Distal mass; RS06 without extra reduction has inadequate knee sustained-load margin</td><td>Not selected</td></tr></table></div><p>A shaft/bevel system is not automatically stiffer. Verify θshaft = TL/(GJ), J = π(do⁴−di⁴)/32, then reflect its compliance through the gear ratio and add gear-mesh/bearing/housing compliance. Check bevel bending/contact fatigue, pinion tangential force 2T/dpitch, axial/radial thrust, alignment and lubrication. If adopted, preserve <b>2:1 total external reduction</b>, not 2:1 at both bevel meshes. Gear module, face width and shaft diameter remain unreleased until geometry and fatigue loads are defined.</p></section>
<section><h2>Wheels: the all-RobStride limit</h2><p><b>Do not order wheel motors from this report.</b> RS06 is the leg selection, not a justified wheel substitution. Even using its nominal 480 rpm no-load endpoint and 95% assumed external efficiency:</p><div class="eq">To retain 23.7 Nm peak: N ≥ 23.7 / (0.95 × 36) = 0.693<br>To reach 79.00 rad/s: N ≤ (480 × 2π/60) / 79.00 = 0.636<br>No overlap; loaded speed makes the conflict worse.</div><p>N &lt;1 is a speed-increasing transmission. The 79 rad/s sample is braking, so this simplified motoring endpoint test alone is not a braking proof. However, RR also reaches 76.25 rad/s in motoring and FR drives at 21.02 Nm / 61.50 rad/s. A loaded, four-quadrant wheel design is still required. Choose either a non-RobStride faster wheel motor or explicitly test a reduced wheel envelope before releasing wheel hardware; neither change is made here.</p></section>
<section><h2>Release checklist</h2><ul><li>Obtain exact RS06 revision, CAD model, available stock and quote. Manufacturer source dated 13 July 2026 takes precedence over older conflicting web snippets for this screen.</li><li>CAD: preserve joint axes and link lengths; include pulley bearings, tensioner, guard, actual-knee encoder and cooling path. Reconcile each link's mass, COM and inertia.</li><li>Bench: calibrated joint torque, repeated captured waveforms, low-speed holding, thermal soak, minimum battery voltage, braking/regen, belt reversal stiffness and tooth-jump tests.</li><li>Control: integrated RS06 drive/CAN integration, explicit joint-coordinate torque cap and speed envelope, watchdog and independent emergency stop. Do not apply the 23.5 Nm knee cap at the module output: with 2:1 gearing that would nearly double joint torque.</li><li>Battery/PCB: 48 V nominal curve is not a battery-pack selection. Keep actual bus inside allowed limits, including full charge and regen; size discharge protection from synchronized electrical measurements/model.</li><li>Simulation: add RS06 and transmission inertia, friction, backlash/compliance and real torque–speed/thermal limits to a separate configuration. Do not silently mutate the accepted baseline.</li></ul><details><summary>Sources and model assumptions</summary><p>Vendor specification: <a href="{SPEC}">2026-07-13 PDF</a>, pages 31–33. PDF SHA-256: <code>79576e55fee940ce4e718ceffabb31ecb9fd49c9ecf2dd7ddd5d050a31eeebee</code>. RobStride Product_Information repository, official retail home page, first-hand Go2 teardown and Gates belt guidance checked 2026-09-10. Raw run hashes are in the companion test report.</p><p>Assumptions: nominal 48 V curve; 95% forward belt efficiency (90% sensitivity stated); linear interpolation between loaded points; no loaded extrapolation above 430 rpm; peak screen extended flat below 280 rpm. No electrical/thermal dynamic fit, regeneration curve or guaranteed production tolerance is implied. Source torque estimates precede velocity by ~5 ms.</p></details></section>'''
    page('RobStride motor selection · Rev 1','RS06 leg baseline, 2:1 knee belt reduction, actual trajectory checks and a clear wheel limitation.',body,'robstride-motor-selection.html')

